# Collect names from staging outputs
SPLIT = r"\s*(?:/|,|&|\band\b|\||\n)\s*"
found   = {}   # name -> set of "file:column"
skipped = []

for f in mssparkutils.fs.ls(f"{ROOT}/{STAGING_DIR}"):
    if not f.name.lower().endswith(".csv"):
        continue
    if not f.isDir and f.size == 0:
        skipped.append((f.name, "empty file"))
        continue
    try:
        df = spark.read.option("header", True).option("multiLine", True).csv(f.path).toPandas()
    except Exception as e:
        skipped.append((f.name, type(e).__name__))
        continue
    for col in [c for c in USER_COLUMNS if c in df.columns]:
        print(f"Scanning {f.name} -> {col}")
        for val in df[col].dropna():
            for name in re.split(SPLIT, str(val)):
                if name.strip():
                    found.setdefault(name.strip(), set()).add(f"{f.name}:{col}")

for name, why in skipped:
    print(f"Skipped {name}: {why}")
print(f"Distinct names found: {len(found)}")

# Match names to Entra
def pick(hits):
    """One hit -> it. Several (same person, two accounts) -> prefer active, then the one with a mailbox."""
    hits = list(dict.fromkeys(hits))
    if len(hits) <= 1:
        return hits[0] if hits else None
    rows = ENTRA_BY_ID.loc[hits]
    for mask in [~rows["deleted"], rows["mail"].notna()]:
        if mask.sum() == 1:
            return rows[mask].index[0]
        if mask.sum() > 1:
            rows = rows[mask]
    return None   # still ambiguous -> needs NAME_OVERRIDES

def match(name):
    if name in NAME_OVERRIDES:
        key  = NAME_OVERRIDES[name].lower()
        uid  = pick(by_upn.get(key, []) or by_mail.get(key, []))
        return (uid, "override") if uid else (None, "override not found")
    k = clean_display(name)
    for method, idx in [("displayName", by_display), ("first+last", by_name)]:
        hits = idx.get(k, [])
        if hits:
            uid = pick(hits)
            return (uid, method) if uid else (None, f"ambiguous ({len(set(hits))} accounts)")
    return None, "unmatched"

rows = []
for name, where in sorted(found.items()):
    uid, method = match(name)
    rows.append({"name": name, "entraId": uid, "method": method, "foundIn": "; ".join(sorted(where))})
name_map = pd.DataFrame(rows)

matched   = name_map[name_map.entraId.notna()]
unmatched = name_map[name_map.entraId.isna()]
print(f"Matched: {len(matched)} | Unmatched/ambiguous: {len(unmatched)}")
display(unmatched) if len(unmatched) else print("All names matched")
